function anim(){cancelAnimationFrame(raf);const s=performance.now(),dur=800,from=promises.map(p=>({x:p.x,y:p.y}));function step(t){const e=Math.min(1,(t-s)/dur),k=1-Math.pow(1-e,3);promises.forEach((p,i)=>{p.x=from[i].x+(p.tx-from[i].x)*k;p.y=from[i].y+(p.ty-from[i].y)*k;});render();if(e<1)raf=requestAnimationFrame(step);}raf=requestAnimationFrame(step);}
function targets(mode){const n=promises.length;if(!n)return;computeBox();const bx=box.x,by=box.y,bw=box.w,bh=box.h,cx=bx+bw/2,cy=by+bh/2;const from=promises.map(p=>({x:p.x,y:p.y}));
  if(mode==='inspi'){promises.forEach(p=>{p.x=bx+rand(.12,.88)*bw;p.y=by+rand(.12,.88)*bh;});lloyd(5);}
  else if(mode==='date'){const s=[...promises].sort((a,b)=>a.due-b.due);const cols=3;s.forEach((p,i)=>{p.x=bx+bw*(0.22+(i%cols)*0.28);p.y=by+bh*(0.12+Math.floor(i/cols)*0.2);});lloyd(1);}
  else if(mode==='urgence'){promises.forEach(p=>{const u=1/(p.due+1);const ang=rand(0,6.28);const r=(1-u)*Math.min(bw,bh)*.42+rand(0,16);p.x=cx+Math.cos(ang)*r;p.y=cy+Math.sin(ang)*r;});lloyd(2);}
  else if(mode==='personne'){const ord=[...new Set(promises.map(p=>p.who))];const idx={};promises.forEach(p=>{const gi=ord.indexOf(p.who);idx[gi]=(idx[gi]||0);const k=idx[gi]++;p.x=bx+bw*((gi+.5)/ord.length)+rand(-10,10);p.y=by+bh*(0.16+(k%5)*0.16);});lloyd(1);}
  else if(mode==='nuee'){const g=[...new Set(promises.map(p=>p.nuee||'__s'))];const ctr={};g.forEach((gg,i)=>{const ang=(i/g.length)*6.28;ctr[gg]=[cx+Math.cos(ang)*bw*.24,cy+Math.sin(ang)*bh*.24];});promises.forEach(p=>{const c=ctr[p.nuee||'__s'];p.x=c[0]+rand(-24,24);p.y=c[1]+rand(-24,24);});lloyd(2);}
  promises.forEach(p=>{p.x=Math.max(bx+6,Math.min(bx+bw-6,p.x));p.y=Math.max(by+6,Math.min(by+bh-6,p.y));});
  promises.forEach((p,i)=>{p.tx=p.x;p.ty=p.y;p.x=from[i].x;p.y=from[i].y;});state.sort=mode;anim();}

function heroIndex(){let bi=-1,bd=1e9;promises.forEach((p,i)=>{if(p.status==='encours'&&!p.enLair&&p.due!=null&&p.due<bd){bd=p.due;bi=i;}});return bi;}
