      if(st.trame&&i!==hero&&ct)out+='<circle cx="'+ct[0].toFixed(1)+'" cy="'+ct[1].toFixed(1)+'" r="3.2" fill="'+RS(HX(pal[p.id%pal.length]))+'"/>';
