function _aQui(w,maj){var s=String(w||'');var r=/^le\s/i.test(s)?'au '+s.slice(3):(/^les\s/i.test(s)?'aux '+s.slice(4):'\u00e0 '+s);return maj?r.charAt(0).toUpperCase()+r.slice(1):r;}
window._aQui=_aQui;
