  var FOND = { tenue:'#8FE08F', atenir:'#DD4D23', encours:'', brouillon:'' };
  var ENCRE= { tenue:'#00341A', atenir:'#FFFFFF', encours:'', brouillon:'' };
  dp.classList.remove('f-tenue','f-atenir','f-encours','f-brouillon');
