  for(var k=0;k<n;k++){ var s=seeds[k]; X[k]=s.px==null?s.x:s.px; Y[k]=s.py==null?s.y:s.py; Wt[k]=s.w||0; if(Wt[k]>mw) mw=Wt[k];
    if(X[k]<x0)x0=X[k]; if(X[k]>x1)x1=X[k]; if(Y[k]<y0)y0=Y[k]; if(Y[k]>y1)y1=Y[k]; }
