function cOf(s,now){var g0=s.gc||(s.gc=_shadeG(s.gray,s.tone,s.shade));if(s.kind==='gray'&&(s.t0===0||now-s.t0>760))return g0;var p=ease((now-s.t0)/760);var to=s.ci!=null?(s.rgb||((palKey==='signal'&&!s.apercu&&!s.choisi)?PALL()[s.nat!=null?s.nat:3][s.lit|0]:PALL()[s.ci][s.lit|0])):g0;   /* ⚑ v27 (Tom, Q307 tranché) : « sous Ingénu, un ton de palette CHOISI À LA MAIN passe devant la nature, comme le code libre le fait déjà. Ingénu colore par nature PAR DÉFAUT ; un choix explicite prime toujours. » */   /* ⚑ v17 INGÉNU (Tom) : la couleur dit la nature — Promi 0 bleu, Chiche 1 rose, Nuée 2 lilas ; une cellule sans parole prend le crème dalle (3) ; un code libre du Cercle, choisi à la main, passe toujours devant */   /* ⚑ Cercle · LA COULEUR (Tom 13 sept.) : un code libre passe devant la palette — jamais sur une dalle masquée (ci nul) */var c=[g0[0]+(to[0]-g0[0])*p,g0[1]+(to[1]-g0[1])*p,g0[2]+(to[2]-g0[2])*p];for(var q=0;q<3;q++){if(c[q]>255)c[q]=255;if(c[q]<0)c[q]=0;}return c;}
function Rpix(now,x0,y0,x1,y1){var STEP=5*UK,_G=_grilleProp();g.setTransform(DPR,0,0,DPR,0,0);for(var sy=0;sy<H;sy+=STEP){for(var sx=0;sx<W;sx+=STEP){var lx=(sx+STEP/2-view.ox)/view.s,ly=(sy+STEP/2-view.oy)/view.s;if(lx<0||lx>W||ly<0||ly>H)continue;var bi=0;if(_G){bi=_G.prop(lx,ly).bi;}else{var bd=1e18,bi=0;for(var k=0;k<seeds.length;k++){var _kx=seeds[k].px==null?seeds[k].x:seeds[k].px,_ky=seeds[k].py==null?seeds[k].y:seeds[k].py,dx=lx-_kx,dy=ly-_ky,d=Math.sqrt(dx*dx+dy*dy)-seeds[k].w;if(d<bd){bd=d;bi=k;}}}var c=cOf(seeds[bi],now);g.fillStyle='rgb('+(c[0]|0)+','+(c[1]|0)+','+(c[2]|0)+')';g.fillRect(sx,sy,STEP+UK,STEP+UK);}}}
