function Rsil(now,x0,y0,x1,y1){var _G=_grilleProp();g.lineCap='round';g.lineJoin='round';var SP=6*UK,AMP=4.5*UK,WL=0.018/UK,LS=6*UK;function wv(xx,ln){return AMP*Math.sin(xx*WL+ln*.55)+AMP*.62*Math.sin(xx*WL*2.4-ln*.42+1.2);}var li=Math.floor(y0/SP);for(var bY=li*SP+SP*.5;bY<y1;bY+=SP,li++){var sX=Math.max(0,x0),run=[],rk=null,rcl=false;function flush(){if(run.length>1){g.beginPath();g.strokeStyle='rgb('+rk+')';g.lineWidth=(rcl?1.5:0.85)*UK;g.moveTo(run[0][0],run[0][1]);for(var q=1;q<run.length;q++)g.lineTo(run[q][0],run[q][1]);g.stroke();}}for(var x=sX;x<=x1;x+=LS){var y=bY+wv(x,li);var s=_G?seeds[_G.prop(x,bY).bi]:cAt(x,bY),c=cOf(s,now),key=(c[0]|0)+','+(c[1]|0)+','+(c[2]|0);if(rk!==null&&key!==rk){var last=run[run.length-1];flush();run=[last];}run.push([x,y]);rk=key;rcl=(s.kind!=='gray');}flush();}}
