    if(rx1-rx0<8||ry1-ry0<8) return false;
    lx0=lx0+(rx0-sx)/(view.s*DPR); ly0=ly0+(ry0-sy)/(view.s*DPR);
    lw=(rx1-rx0)/(view.s*DPR); lh=(ry1-ry0)/(view.s*DPR);
