  if(window._shGelCadrage){ pts[e.pointerId]={x:e.clientX,y:e.clientY};
    px=e.clientX; py=e.clientY; mx0=window.shPanX; my0=window.shPanY; return; }
  pts[e.pointerId]={x:e.clientX,y:e.clientY};
  var c=ctr();
