  K.MOT_INK = 2.5;
  K.AIR_MOT = 38.18 - K.MOT_INK;
  K.BOULE_BAS = K.bo.y + K.bo.d/2 + K.bo.d*K.R;                          /* 353,4 — la BOULE, pas sa boîte */
  K.AIR = 28;
  K.PLI = 844;
