    var m=plantation?(p.monde||{}):((window.Toile&&Toile.mondeCourant&&Toile.mondeCourant())||{}); if((m.p||'signal')!=='signal') return null;
    var nat=p.chiche?'chiche':(p.nuee&&p.kind==='nuee'?'nuee':'promi');
